        if(substr($code,$i,8)==='function'&&($i===0||preg_match('/\w/',$code[$i-1])!==1)&&preg_match('/\G\s+[a-zA-Z_][a-zA-Z0-9_]*\s*\(/',$code,$m,0,$i+8)===1){
            $open=strpos($code,'{',$i);if($open===false)throw new RuntimeException('Function extraction failed.');
